class Solution {
public:
    vector<int> pathInZigZagTree(int label) {
        vector<int> path;
        int d = 0;
        while ((1 << d) <= label) d++;
        while (label > 1) {
            path.push_back(label);
            label /= 2;
            d--;
            int lo = 1 << (d - 1);
            int hi = (1 << d) - 1;
            label = lo + hi - label;
        }
        path.push_back(1);
        reverse(path.begin(), path.end());
        return path;
    }
};
